import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/api';

export default function StationDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [station, setStation] = useState(null);
  const [chargers, setChargers] = useState([]);
  const [form, setForm] = useState({ chargerId: '', date: '', startTime: '', endTime: '' });
  const [error, setError] = useState('');

  useEffect(() => {
    api.get(`/stations/${id}`).then(({ data }) => {
      setStation(data.station);
      setChargers(data.chargers);
    });
  }, [id]);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  // Step 4-5: select date/time/charger, then confirm booking
  const handleBook = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const { data } = await api.post('/bookings', { stationId: id, ...form });
      navigate(`/payment/${data._id}`);
    } catch (err) {
      setError(err.response?.data?.message || 'Booking failed');
    }
  };

  if (!station) return <p>Loading station details...</p>;

  return (
    <div className="station-detail">
      <h2>{station.name}</h2>
      <p>{station.address}</p>
      <p>₹{station.pricePerKwh} / kWh · Open {station.openingTime} - {station.closingTime}</p>

      <h3>Available chargers</h3>
      <ul>
        {chargers.map((c) => (
          <li key={c._id}>
            {c.chargerCode} · {c.type} · {c.powerKw} kW ·{' '}
            {c.isAvailable ? 'Available' : 'In use'}
          </li>
        ))}
      </ul>

      <h3>Book a slot</h3>
      {error && <p className="error">{error}</p>}
      <form onSubmit={handleBook}>
        <select name="chargerId" onChange={handleChange} required>
          <option value="">Select a charger</option>
          {chargers.filter((c) => c.isAvailable).map((c) => (
            <option key={c._id} value={c._id}>{c.chargerCode} - {c.type} ({c.powerKw} kW)</option>
          ))}
        </select>
        <input type="date" name="date" onChange={handleChange} required />
        <input type="time" name="startTime" onChange={handleChange} required />
        <input type="time" name="endTime" onChange={handleChange} required />
        <button type="submit">Confirm booking</button>
      </form>
    </div>
  );
}
